steps.output:
def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(v for v in set(grid[0]) if all(x == v for x in grid[0])) if any(len(set(row)) == 1 for row in grid) else None
    if sep is None:
        sep = max(set(x for row in grid for x in row), key=lambda v: sum(x == v for row in grid for x in row))
    rs = [i for i, row in enumerate(grid) if all(x == sep for x in row)]
    cs = [j for j in range(w) if all(grid[i][j] == sep for i in range(h))]
    def ranges(n, cuts):
        out=[]; start=0
        for c in cuts:
            if c > start: out.append((start,c))
            start=c+1
        if start<n: out.append((start,n))
        return out
    bands, panels = ranges(h,rs), ranges(w,cs)
    # The first panel in each horizontal band carries the color to use for that band.
    colors=[]
    for r0,r1 in bands:
        vals=[grid[i][j] for i in range(r0,r1) for j in range(panels[0][0],panels[0][1]) if grid[i][j] != 0 and grid[i][j] != sep]
        colors.append(vals[0])
    # A nonempty design in any panel other than the color-key column is the template.
    shape=None
    for r0,r1 in bands:
        for c0,c1 in panels[1:]:
            pts=[(i-r0,j-c0) for i in range(r0,r1) for j in range(c0,c1) if grid[i][j] not in (0,sep)]
            if pts:
                shape=pts
                break
        if shape is not None: break
    out=[row[:] for row in grid]
    for (r0,r1), color in zip(bands,colors):
        for c0,c1 in panels:
            for dr,dc in shape:
                out[r0+dr][c0+dc]=color
    return out

